API Gateway / Ingress Container.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

title Component diagram for the API Gateway / Ingress Container container

Container_Boundary(api_gateway_ingress_container, "API Gateway / Ingress Container") {
    Component(Ingress_Router, "Ingress Router", "AWS API Gateway / Envoy / Nginx", "Managed ingress routing, TLS termination, and traffic entry point.")
    Component(Rate_Limiter_and_Idempotency_Validator, "Rate Limiter & Idempotency Validator", "Amazon ElastiCache (Redis)", "Validates idempotency keys and tracks rate limits to prevent duplicate processing.")
    Component(Payload_Validator, "Payload Validator", "OpenAPI / JSON Schema", "Performs strict boundary validation and automated schema checks.")
}

Rel(Ingress_Router, Payload_Validator, "Forwards incoming REST requests for schema validation", "HTTPS")
Rel(Payload_Validator, Rate_Limiter_and_Idempotency_Validator, "Checks idempotency keys and rate limits", "Redis Protocol")

@enduml

Case Management Container.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

Container_Boundary(case_management_container, "Case Management Container") {
    Component(Case_Workflow_Controller, "Case Workflow Controller", "Finite State Machine & REST API", "Manages analyst case workflows, state transitions, and standardized error handling using RFC 7807.")
    Component(Case_Service_Layer, "Case Service Layer", "Service Layer Pattern", "Implements business logic for reviewing flagged transactions and processing fraud analyst decisions.")
    Component(Case_Repository, "Case Repository", "Repository Pattern & Optimistic Concurrency Control", "Handles data access operations and persists case states and transactional integrity.")
}

Rel(Case_Workflow_Controller, Case_Service_Layer, "Delegates workflow requests and business operations", "Invokes")
Rel(Case_Service_Layer, Case_Repository, "Persists and retrieves case states", "TCP/SQL")

@enduml

Amazon S3.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

title Component diagram for the Amazon S3 container

System_Ext(RealTimeScoringContainer, "Real-Time Scoring Container", "External consumer container")
System_Ext(AuditLoggingContainer, "Audit Logging Container", "External consumer container")

Container_Boundary(AmazonS3, "Amazon S3") {
    Component(ModelArtifactsStore, "Model Artifacts Store", "Content-Addressable Storage with SSE-KMS", "Stores versioned model tar.gz artifacts for the Real-Time Scoring Container.")
    Component(TamperEvidentAuditLogStore, "Tamper-Evident Audit Log Store", "Object Lock WORM Storage with Glacier Lifecycle", "Maintains tamper-evident audit records in compliance mode with automated lifecycle tiering for 7-year retention.")
}

Rel(RealTimeScoringContainer, ModelArtifactsStore, "Asynchronously downloads model artifacts via local caching sidecars", "")
Rel(AuditLoggingContainer, TamperEvidentAuditLogStore, "Writes tamper-evident audit logs via AWS VPC Gateway Endpoints with Object Lock enabled", "")

@enduml

AWS SQS / Kinesis.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

System_Boundary(aws_sqs_kinesis, "AWS SQS / Kinesis") {
    Component(AWS_SQS_FIFO, "AWS SQS FIFO", "AWS SQS FIFO with S3 payload referencing", "Guarantees strict ordering, exact-once processing, and bypasses 256 KB message limits for decision events.")
}

Rel(Real-Time Scoring Container, AWS_SQS_FIFO, "Asynchronously dispatches decision events using SendMessage")
Rel(AWS_SQS_FIFO, Audit Logging Container, "Delivers decision events using ReceiveMessage and DeleteMessage")
@enduml

AWS Secrets Manager / Parameter Store.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

Container_Boundary(aws_secrets_manager_parameter_store, "AWS Secrets Manager / Parameter Store") {
    Component(Secrets_Retrieval_Engine, "Secrets Retrieval Engine", "AWS SDK / KMS", "Fetches and decrypts database credentials, API keys, and configuration parameters securely at runtime.")
    Component(Caching_and_Rotation_Controller, "Caching and Rotation Controller", "AWS Lambda / IAM", "Manages local in-memory caching of secrets and automates periodic credential rotation to enhance security.")
}

Rel(Secrets_Retrieval_Engine, Caching_and_Rotation_Controller, "Populates and updates cached secrets", "")

@enduml
